1/jour — &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-(Capacit&#233;).html&quot; title=&quot;Convocation (Mag)&quot;&gt;convocation&lt;/a&gt; (niveau 4, 3 &lt;a class=&quot;pagelink&quot; href=&quot;&#201;rinye.html&quot; title=&quot;Diable, &#201;rinye&quot;&gt;&#233;rinyes&lt;/a&gt; 60%)
